/**
 * Prose search: types and helpers around the build-time Pagefind index.
 *
 * The index is generated by scripts/build-search.ts (postbuild) into
 * out/pagefind/. At runtime the browser loads /pagefind/pagefind.js lazily,
 * on the first query, via createPagefindClient(). Everything else in this
 * file is pure and unit-tested.
 *
 * Structured-entity search (MiniSearch over methods, companies, datasets)
 * is the other half of this same stack: lib/structured-search.ts builds the
 * documents and the integrity check; scripts/build-search.ts emits
 * public/search-index.json after the Pagefind step. The SearchClient
 * interface and the results area in components/search/ remain the UI seams.
 */

import { foldGreekToAscii } from './greek-transliteration';
import { PUBLIC_IDENTITY } from './identity';

/** One rendered prose result. */
export type SearchHit = {
  /** Path of the matching page, e.g. "/manipulation/action-chunking/". */
  url: string;
  /** Page title with the site-name suffix stripped (falls back to the URL). */
  title: string;
  /** Match-context snippet; may contain <mark> highlight markup. */
  excerpt: string;
};

/** Minimal search backend contract. Pagefind satisfies it for prose. */
export interface SearchClient {
  search(query: string): Promise<SearchHit[]>;
}

/** Cap on rendered prose results. Pagefind ranks by relevance. */
export const RESULT_LIMIT = 20;

/**
 * The site-name tail Pagefind appends to result titles, taken from the
 * <title> template in app/layout.tsx ('%s | Robot Wiki'). Both derive the
 * name from PUBLIC_IDENTITY, or every search result renders with a visible
 * site-name suffix.
 */
const SITE_TITLE_SUFFIX = ` | ${PUBLIC_IDENTITY}`;

/* The subset of the Pagefind runtime API this app consumes. */
export interface PagefindResultData {
  url: string;
  meta?: { title?: string };
  anchors?: { element: string; text: string; location: number }[];
  excerpt?: string;
  plain_excerpt?: string;
  sub_results?: { title: string; url: string }[];
  content?: string;
}

export interface PagefindResult {
  data: () => Promise<PagefindResultData>;
}

export interface PagefindSearchResponse {
  results: PagefindResult[];
}

/**
 * The one tokenizer both sides of the genuineness check must use.
 *
 * Every non-alphanumeric character is a boundary, so "sim-to-real" and
 * "pi0.5" split the same way whether they arrive as a query or as page
 * content. Splitting the query on a narrower set than the content is what
 * silently discarded whole query classes twice: a hyphenated query
 * collapsed to "simtoreal" until the dash was added to the split set, and
 * the period then did the same thing to every version-numbered query
 * ("pi0.5" became "pi05", which can never prefix-match ["pi0", "5"]).
 *
 * Greek letters fold to their ASCII names so the wiki's Greek-lettered
 * model names match the spelling a reader types, matching the folding the
 * structured index applies (lib/greek-transliteration.ts).
 */
function tokenize(value: string): string[] {
  return foldGreekToAscii(value)
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
}

/**
 * Pagefind truncates terms it cannot find until something matches: the
 * garbage query "zzqqxx" returns a hit whose excerpt marks "Z.". Those
 * fallback hits are indistinguishable by score, and the excerpt window can
 * miss the real match entirely (for "covariate" Pagefind excerpted and
 * marked "co-training"), so the excerpt cannot arbitrate. The full page
 * content can: a hit is genuine only if every query token is a prefix of
 * some word in the page content (exact matches and the typeahead case,
 * e.g. "tempor" matching "temporal"). Hits without content are kept, since
 * we cannot disprove them.
 */
export function isGenuineHit(query: string, content: string): boolean {
  const tokens = tokenize(query);
  if (tokens.length === 0) return false;
  if (!content.trim()) return true;
  const words = tokenize(content);
  return tokens.every((token) =>
    words.some((word) => word.startsWith(token)),
  );
}

function stripSiteSuffix(rawTitle: string | undefined, url: string): string {
  const trimmed = rawTitle?.trim();
  if (!trimmed) return url;
  return trimmed.endsWith(SITE_TITLE_SUFFIX)
    ? trimmed.slice(0, -SITE_TITLE_SUFFIX.length)
    : trimmed;
}

/**
 * How strongly a result's own title answers the query. Two tiers, because
 * they mean different things to a reader: 2 is the page that is ABOUT the
 * query (its title carries the whole query phrase), 1 is a page whose title
 * touches every query term without being named for the phrase, 0 is a page
 * that merely mentions it in the body.
 *
 * Pagefind ships no title field and no ranking configuration, so without
 * this an article ties with every index page that lists it. Since the
 * non-article destinations were added to the index, the home page and a
 * domain landing legitimately mention every article they link, which made
 * "the mention outranks the page itself" the common case rather than an
 * edge one.
 */
export function titleWeight(query: string, title: string): number {
  const queryTokens = tokenize(query);
  if (queryTokens.length === 0) return 0;
  const titleTokens = tokenize(title);
  if (titleTokens.length === 0) return 0;

  const phrase = queryTokens.join(' ');
  if (titleTokens.join(' ').includes(phrase)) return 2;

  return queryTokens.every((token) =>
    titleTokens.some((word) => word.startsWith(token)),
  )
    ? 1
    : 0;
}

/**
 * Whether the query appears as one contiguous token sequence in the page
 * content. Tokens use the same punctuation and Greek folding as the
 * genuineness check, and retain its typeahead behavior: "tempor ensemb"
 * matches "temporal ensembling". This is deliberately a secondary signal
 * behind titleWeight. It distinguishes a page that actually contains the
 * requested phrase from pages where the same common words occur far apart,
 * which otherwise lets the exact page fall beyond RESULT_LIMIT.
 */
export function contentPhraseWeight(query: string, content: string): number {
  const queryTokens = tokenize(query);
  if (queryTokens.length === 0 || !content.trim()) return 0;
  const contentTokens = tokenize(content);
  if (queryTokens.length > contentTokens.length) return 0;

  for (let start = 0; start <= contentTokens.length - queryTokens.length; start += 1) {
    let matches = true;
    for (let offset = 0; offset < queryTokens.length; offset += 1) {
      if (!contentTokens[start + offset].startsWith(queryTokens[offset])) {
        matches = false;
        break;
      }
    }
    if (matches) return 1;
  }
  return 0;
}

/**
 * Maps a raw Pagefind response to ranked, renderable hits.
 *
 * Order of operations is load-bearing. Every raw result is resolved and
 * tested for genuineness FIRST, and only the survivors are capped: capping
 * the raw list first threw away a genuine hit the index happened to rank
 * just past the cap while a truncation-fallback hit inside the cap took its
 * place, so the rendered count fell below the cap with nothing to show that
 * anything had been dropped.
 *
 * Ranking is a stable sort on title weight, then contiguous content phrase,
 * so Pagefind's own relevance order survives intact within each tier.
 */
export async function toSearchHits(
  response: PagefindSearchResponse,
  query: string,
  limit: number = RESULT_LIMIT,
  requiredPhrase?: RegExp,
): Promise<SearchHit[]> {
  const data = await Promise.all(
    response.results.map((result) => result.data()),
  );
  return data
    .filter((entry) => isGenuineHit(query, entry.content ?? '')
      && (!requiredPhrase || requiredPhrase.test(entry.content ?? '')))
    .map((entry, index) => {
      const title = stripSiteSuffix(entry.meta?.title, entry.url);
      return {
        entry,
        title,
        index,
        titleWeight: titleWeight(query, title),
        phraseWeight: contentPhraseWeight(query, entry.content ?? ''),
      };
    })
    .sort(
      (a, b) =>
        b.titleWeight - a.titleWeight ||
        b.phraseWeight - a.phraseWeight ||
        a.index - b.index,
    )
    .slice(0, limit)
    .map(({ entry, title }) => ({
      url: entry.url,
      title,
      excerpt: resultExcerpt(entry, title, query),
    }));
}

/**
 * Latest-wins sequencing for overlapping searches. Each new query begins a
 * token; only the most recent token may apply its results, so a slow
 * response for an older query can never mix into newer results
 */
export function createRequestSequencer(): {
  begin(): number;
  isCurrent(token: number): boolean;
  invalidate(): void;
} {
  let latest = 0;
  return {
    begin() {
      latest += 1;
      return latest;
    },
    isCurrent(token: number) {
      return token === latest;
    },
    invalidate() {
      latest += 1;
    },
  };
}

type RankedResult = PagefindResult & { id: string; score: number };
type PagefindLookup = (query: string) => Promise<{ results: RankedResult[] }>;

const QUESTION_FILLER = new Set(`
  a an and are as at be been can could did do does for from give had has have how
  i if in into is it its know me much my of on or our own real s should so that the
  their them these this to use uses using was we were what when where whether which
  who why will with without would you your
`.trim().split(/\s+/));

function singular(word: string) {
  return word.length > 3 && word.endsWith('s') && !/(ss|ics)$/.test(word) ? word.slice(0, -1) : word;
}

function questionTerms(query: string) {
  const words = tokenize(query);
  if (words.length < 4) return [];
  const startsWithQuestion = /^(how|what|why|when|which|where|who|can|could|did|does|is|are|will)$/.test(words[0]);
  if (!startsWithQuestion && !/\?\s*$/.test(query)) return [];
  const terms = new Map<string, string>();
  for (const word of words) {
    if (!QUESTION_FILLER.has(word)) terms.set(singular(word), word);
  }
  return terms.size >= 2 && terms.size <= 10 ? [...terms.values()] : [];
}

/** Verify that several terms occur together. Pagefind flattens tables into one
 * string, so a matching window is evidence for ranking, never display copy. */
function questionPassage(content: string, weights: Map<string, number>) {
  const words = content.trim().split(/\s+/u);
  const present = new Set<string>();
  let location: number | undefined;
  let bestWeight = 0;
  for (let start = 0; start < words.length; start += 20) {
    const passage = words.slice(start, start + 40);
    const tokens = tokenize(passage.join(' ')).map(singular);
    const matched = new Set(tokens.filter((word) => weights.has(word)));
    for (const word of matched) present.add(word);
    if (matched.size < Math.max(2, Math.ceil(weights.size / 2))) continue;
    const weight = [...matched].reduce((sum, word) => sum + weights.get(word)!, 0);
    if (weight > bestWeight) {
      bestWeight = weight;
      // Resolve the section at an actual query word, including a window that
      // straddles a heading. Pagefind anchor locations count raw content words.
      const first = passage.findIndex((word) => tokenize(word).some((token) => weights.has(singular(token))));
      location = start + first;
    }
  }
  return { present, location };
}

async function questionExcerpt(data: PagefindResultData, location: number, weights: Map<string, number>) {
  // An article can mention a topic in a comparison table before its own section.
  // Prefer a heading that itself matches most of the query's evidence.
  const headings = data.anchors?.filter((anchor) => anchor.element === 'h2') ?? [];
  const total = [...weights.values()].reduce((sum, value) => sum + value, 0);
  const named = headings.find((heading) => {
    const words = new Set(tokenize(heading.text).map(singular).filter((word) => weights.has(word)));
    const weight = [...words].reduce((sum, word) => sum + weights.get(word)!, 0);
    return words.size >= 2 && weight > total / 2;
  });
  const section = named ?? headings.findLast((heading) => heading.location <= location);
  let text = section?.text.trim() ?? '';
  const route = !text && /^\/([^/]+)\/([^/]+)\/$/.exec(data.url);
  if (route) {
    // Load the small title/summary catalog only for an introduction. The
    // masthead uses this same text, and Pagefind's indexed input stays intact.
    const { getModule } = await import('../data/modules');
    text = getModule(route[1], route[2])?.summary ?? '';
  }
  return escapeExcerpt(text);
}

function escapeExcerpt(text: string) {
  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
}

/** Pagefind sometimes spends its entire opening window on the page title,
 * its short description, and half of the next sentence. Only replace that
 * kind of window. A match inside the article keeps Pagefind's own context. */
function resultExcerpt(entry: PagefindResultData, title: string, query: string) {
  const plain = entry.plain_excerpt;
  const content = entry.content;
  const original = entry.excerpt ?? '';
  if (!plain || !content?.startsWith(plain) || !plain.startsWith(title)) return original;

  const boundary = /^(?:[.!?。！？]\s*|\s+|$)/u.exec(content.slice(title.length));
  if (!boundary) return original;
  const offset = title.length + boundary[0].length;
  const body = content.slice(offset).trimStart();
  if (!body) return '';

  // Pagefind inserts a full stop between the heading and its authored deck.
  // Sentence segmentation preserves decimals, initials and non-Latin stops.
  const lead = sentenceBreaks?.segment(body.slice(0, 241)).containing(0)?.segment.trim() ?? '';
  const complete = !!lead && lead.length <= 240 && (lead === body || /[.!?。！？][”’"')\]]*$/u.test(lead));
  const rest = plain.slice(offset).trim();
  const terms = tokenize(query);
  const matches = (text: string, term: string) => tokenize(text).some(word =>
    /\p{N}/u.test(term) ? word === term : word.startsWith(term));
  const qualifiers = terms.filter(term => (!QUESTION_FILLER.has(term) || term === 'real')
    && !matches(title, term));
  const visible = qualifiers.filter(term => matches(rest, term));

  // Prefer the deck when it answers the qualifier. Otherwise a matched
  // section can tell the reader which part covers the rest of their search.
  let preview = complete ? lead : '';
  let score = qualifiers.filter(term => matches(preview, term)).length;
  for (const section of entry.sub_results ?? []) {
    if (!section.url.includes('#') || section.title.length > 240) continue;
    const covered = qualifiers.filter(term => matches(section.title, term));
    if (covered.length > score && visible.every(term => covered.includes(term))) {
      preview = section.title;
      score = covered.length;
    }
  }
  // Keep a rare qualifier, model number or measurement from the original
  // window if the shorter alternatives would hide it.
  if (!preview || !visible.every(term => matches(preview, term))) {
    preview = rest + (rest && rest !== body && !/[.!?。！？][”’"')\]]*$/u.test(rest) ? '…' : '');
  }
  return preview.split(/([\p{L}\p{N}]+)/u).map(part => {
    const escaped = escapeExcerpt(part);
    const word = tokenize(part)[0];
    return word && terms.some(term => word.startsWith(term)) ? `<mark>${escaped}</mark>` : escaped;
  }).join('');
}

const sentenceBreaks = typeof Intl.Segmenter === 'function'
  ? new Intl.Segmenter('en', { granularity: 'sentence' }) : undefined;

/** An exact article title can be qualified by the site's subject, as in
 * "robotic kinematics" or "kinematics of robotics". Body matches can miss the
 * article when its author calls a robot a hand or an arm. */
async function preferQualifiedTitle(query: string, hits: SearchHit[]) {
  const phrase = tokenize(query).join(' ');
  const qualifier = /^(?:robot|robotic|robotics) (.+)$|^(.+) (?:in|of|for) robotics$/.exec(phrase);
  // "Validation data" asks for evidence about a named subject. Only map it
  // when that subject has an entire published evaluation article.
  const validation = /^(.+) (?:validation|evaluation) (?:data|results|evidence)$/.exec(phrase);
  if ((!qualifier && !validation) || hits.some((hit) => titleWeight(query, hit.title) === 2)) return hits;
  const { publishedModules } = await import('../data/modules');
  const article = publishedModules().find((entry) => {
    const title = tokenize(entry.title).join(' ');
    return qualifier ? title === (qualifier[1] ?? qualifier[2])
      : title.replace(/ for robotics$/, '') === `${validation![1]} evaluation`;
  });
  if (!article) return hits;

  const url = `/${article.domain}/${article.slug}/`;
  const lead = hits.find((hit) => hit.url === url)
    ?? { url, title: article.title, excerpt: escapeExcerpt(article.summary) };
  return [lead, ...hits.filter((hit) => hit.url !== url)].slice(0, RESULT_LIMIT);
}

// Only the policy-ranking experiment has been checked for these alternate
// wordings. Leave the rest of the directory to ordinary Pagefind search.
function comparisonTerms(text: string) {
  const words = tokenize(text).filter(word => !QUESTION_FILLER.has(word) || ['real', 'without'].includes(word));
  return new Set(words.map(word => {
    if (/^(rank|order)(s|ed|ing|ings)?$/.test(word)) return 'order';
    if (word === 'actual' || word === 'physical') return 'real';
    if (word === 'hardware') return 'robot';
    if (word.endsWith('ies')) return word.slice(0, -3) + 'y';
    return singular(word);
  }));
}

async function preferPolicyComparison(query: string, hits: SearchHit[]) {
  const words = comparisonTerms(query);
  const simulator = words.has('simulator') || (words.has('world') && words.has('model'));
  const ranking = words.has('order') && (words.has('policy') || words.has('agree') || words.has('agreement'));
  const predicting = words.has('predict') && words.has('policy') && (words.has('work') || words.has('best'));
  if (!simulator || !(ranking || predicting) || !(words.has('trial') || words.has('robot'))) return hits;

  const [{ questionsForArticles }, { getModule }] = await Promise.all([
    import('../data/article-questions'), import('../data/modules'),
  ]);
  const article = getModule('world-models', 'evaluation');
  if (!article || article.status !== 'published') return hits;
  const question = questionsForArticles([article]).find(({href}) => href.endsWith('order-policies-as-real-trials-do'));
  if (!question) return hits;

  const heading = question.href.split('#')[1].replace(/^level-\d+-/, '');
  // The table's column heading is "Agreement with real trials". Every
  // subject word must be accounted for, including names, numbers and task
  // qualifiers such as "flight" in "real flight trials".
  const supported = comparisonTerms(question.label + ' ' + heading + ' agreement agree');
  if (![...words].every(word => supported.has(word))) return hits;

  const path = question.href.split('#')[0];
  const lead = {url: question.href, title: article.title, excerpt: escapeExcerpt(question.label)};
  return [lead, ...hits.filter(hit => hit.url.split('#')[0] !== path)].slice(0, RESULT_LIMIT);
}

/** Try partial matches only for a question whose complete search found nothing. */
async function partialQuestionHits(lookup: PagefindLookup, terms: string[]): Promise<SearchHit[]> {
  const searches = await Promise.all(terms.map((term) => lookup(term)));
  const weights = new Map<string, number>();
  const pages = new Map<string, { result: RankedResult; total: number; scores: Map<string, number> }>();
  searches.forEach(({ results }, index) => {
    const term = singular(terms[index]);
    // A rare word such as a dataset name carries more evidence than "robot".
    weights.set(term, 1 / Math.sqrt(1 + results.length));
    for (const result of results) {
      const page = pages.get(result.id) ?? { result, total: 0, scores: new Map<string, number>() };
      page.total += result.score;
      page.scores.set(term, result.score);
      pages.set(result.id, page);
    }
  });
  const totalWeight = [...weights.values()].reduce((sum, weight) => sum + weight, 0);
  // Ranking IDs is cheap. Only fetch bodies from the leading candidates.
  const candidates = [...pages.values()].sort((a, b) => b.total - a.total).slice(0, 12);
  const inspected = await Promise.all(candidates.map(async ({ result, scores }) => {
    const data = await result.data();
    const { present, location } = questionPassage(data.content ?? '', weights);
    const weight = [...present].reduce((sum, word) => sum + weights.get(word)!, 0);
    // Require support for most words and most of the information they carry.
    if (location === undefined || present.size < Math.ceil(terms.length * 0.6) || weight <= totalWeight / 2) return null;
    const score = [...present].reduce((sum, word) => sum + (scores.get(word) ?? 0), 0);
    const hit = { url: data.url, title: stripSiteSuffix(data.meta?.title, data.url), excerpt: await questionExcerpt(data, location, weights) };
    return { hit, score };
  }));
  return inspected.filter((entry) => entry !== null)
    .sort((a, b) => b.score - a.score)
    .slice(0, 3)
    .map(({ hit }) => hit);
}

export async function searchPagefind(lookup: PagefindLookup, query: string): Promise<SearchHit[]> {
  let strict = await preferQualifiedTitle(query, await toSearchHits(await lookup(query), query));
  // Papers and readers use “sim2real” for the wiki’s “sim-to-real”. Keep any
  // literal results first, and keep the reader's other terms in the lookup.
  if (!strict.length) {
    const expanded = query.replace(/(?<![\p{L}\p{N}_-])sim2real(?![\p{L}\p{N}_-])/giu, 'sim-to-real');
    if (expanded !== query) {
      strict = await toSearchHits(await lookup(expanded), expanded, RESULT_LIMIT, /\bsim[\s\p{Pd}]+to[\s\p{Pd}]+real\b/iu);
    }
  }
  const terms = questionTerms(query);
  if (!terms.length) return strict;
  const hits = strict.length ? strict : await partialQuestionHits(lookup, terms);
  return preferPolicyComparison(query, hits);
}

/**
 * Loads the Pagefind runtime and adapts it to SearchClient.
 *
 * The import specifier must stay invisible to the bundler: pagefind.js is
 * emitted by the postbuild indexing step and does not exist when Next.js
 * bundles this module. Rejects when the index is unavailable (for example
 * under the dev server, which never serves out/).
 */
export async function createPagefindClient(): Promise<SearchClient> {
  const runtimeImport = new Function(
    'specifier',
    'return import(specifier)',
  ) as (specifier: string) => Promise<unknown>;
  const pagefind = (await runtimeImport('/pagefind/pagefind.js')) as {
    search: PagefindLookup;
  };
  return { search: (query) => searchPagefind((term) => pagefind.search(term), query) };
}
